    fun scheme(id: String, dark: Boolean, highContrast: Boolean): ColorScheme = when (id) {
        "brand" -> if (dark) { if (highContrast) brandDarkHc else brandDark } else { if (highContrast) brandLightHc else brandLight }
        "forest" -> if (dark) { if (highContrast) forestDarkHc else forestDark } else { if (highContrast) forestLightHc else forestLight }
        "sunset" -> if (dark) { if (highContrast) sunsetDarkHc else sunsetDark } else { if (highContrast) sunsetLightHc else sunsetLight }
        "ocean" -> if (dark) { if (highContrast) oceanDarkHc else oceanDark } else { if (highContrast) oceanLightHc else oceanLight }
        "graphite" -> if (dark) { if (highContrast) graphiteDarkHc else graphiteDark } else { if (highContrast) graphiteLightHc else graphiteLight }
        else -> if (dark) { if (highContrast) brandDarkHc else brandDark } else { if (highContrast) brandLightHc else brandLight }
    }
}
